INSERT INTO `table_seo` VALUES (257,16,'product','man_list','san-pham','','','','','','','',''),(258,17,'product','man_list','san-pham','','','','','','','',''),(259,18,'product','man_list','san-pham','','','','','','','',''),(261,42,'product','man','san-pham','','','','','','','',''),(262,43,'product','man','san-pham','','','','','','','',''),(266,44,'product','man','san-pham','','','','','','','',''),(267,45,'product','man','san-pham','','','','','','','',''),(268,46,'product','man','san-pham','','','','','','','',''),(269,47,'product','man','san-pham','','','','','','','',''),(270,48,'product','man','san-pham','','','','','','','',''),(271,49,'product','man','san-pham','','','','','','','',''),(272,50,'product','man','san-pham','Đồng hồ nước Komax','Đồng hồ nước Komax','Đồng hồ nước Komax sản xuất tại Hàn Quốc phân phối bởi Thép Bảo Tín. Các loại Đồng hồ lưu lượng nước Komax do chúng tôi cung cấp luôn bảo đảm nguồn gốc, xuất xứ','','','','',''),(273,51,'product','man','san-pham','','','','','','','',''),(313,52,'product','man','san-pham','','','','','','','',''),(276,53,'product','man','san-pham','','','','','','','',''),(312,54,'product','man','san-pham','','','','','','','',''),(311,55,'product','man','san-pham','','','','','','','',''),(309,56,'product','man','san-pham','','','','','','','',''),(308,57,'product','man','san-pham','','','','','','','',''),(706,59,'product','man','san-pham','Mặt bích inox 316: Giải pháp hoàn hảo cho hệ thống đường ống bền bỉ','','Mặt bích inox 316 - Chống ăn mòn, chịu nhiệt cao, độ bền bỉ, ứng dụng đa dạng trong hệ thống đường ống. Lựa chọn kích thước, áp suất, nhiệt độ phù hợp...','','','','',''),(707,60,'product','man','san-pham','Mặt bích DN 200 là gì? Giải đáp mọi thắc mắc của bạn','','Mua Mặt bích DN 200 giá rẻ, chất lượng cao tại Nam Long. Chúng tôi cung cấp đa dạng các loại Mặt bích DN 200 phù hợp với mọi nhu cầu của bạn.','','','','',''),(627,61,'product','man','san-pham','Khớp Nối Nhanh Ống Hơi - Ưu Điểm, Ứng Dụng Và Cách Sử Dụng','','Khớp nối nhanh ống hơi là phụ kiện không thể thiếu trong các hệ thống khí nén hiện đại. Nó đóng vai trò quan trọng trong việc phân chia dòng khí ra, kết nối các thiết bị khí nén và đảm bảo hoạt động hiệu quả, an toàn.','','','','',''),(624,63,'product','man','san-pham','Mặt bích thép - Giải pháp kết nối đường ống hoàn hảo','','Mặt bích thép là bộ phận quan trọng trong hệ thống đường ống, dùng để kết nối hai đoạn ống lại với nhau một cách chắc chắn và kín khít.','','','','',''),(623,64,'product','man','san-pham','Mặt bích inox JIS 10K - Chất lượng cao, giá tốt, uy tín','','Mặt bích inox JIS 10K được sử dụng rộng rãi trong các hệ thống đường ống, van, máy bơm, ...chúng tôi cam kết mang đến cho khách hàng những sản phẩm tốt nhất.','','','','',''),(622,65,'product','man','san-pham','Co lơi inox đa dạng kích thước, đáp ứng mọi nhu cầu','','Co lơi ren inox là phụ kiện đường ống được sử dụng để kết nối hai đoạn ống có kích thước bằng nhau hoặc khác nhau, tạo thành góc 45 độ so với hướng dòng chảy.','','','','',''),(289,24,'news','man','dich-vu','','','','','','','',''),(290,25,'news','man','dich-vu','','','','','','','',''),(291,26,'news','man','dich-vu','','','','','','','',''),(89,1,'tags','man','san-pham','Giày giá rẻ','Giày giá rẻ','Giày giá rẻ','Cheap shoes','Cheap shoes',NULL,NULL,'Giày giá rẻ'),(22,2,'tags','man','san-pham','Guốc đế thấp','Guốc đế thấp','Guốc đế thấp','Low-base clogs','Low-base clogs',NULL,NULL,'Low-base clogs'),(293,27,'news','man','chinh-sach','','','','','','','',''),(294,28,'news','man','chinh-sach','','','','','','','',''),(296,29,'news','man','tin-tuc','','','','','','','',''),(297,30,'news','man','tin-tuc','','','','','','','',''),(298,31,'news','man','tin-tuc','','','','','','','',''),(318,32,'news','man','vi-sao','','','','','','','',''),(319,33,'news','man','vi-sao','','','','','','','',''),(320,34,'news','man','vi-sao','','','','','','','',''),(322,35,'news','man','vi-sao','','','','','','','',''),(1076,0,'static','update','gioi-thieu','CÔNG TY TNHH SẢN XUẤT VÀ XUẤT NHẬP KHẨU NAM LONG','','Bằng sức trẻ, sự nhiệt huyết mọi thành viên trong gia đình Nam Long luôn phấn đấu không ngừng để tạo nên những sản phẩm chất lượng tốt nhất đến khách hàng.','','','','',''),(1053,95,'product','man','san-pham','Nắp mương - Giải pháp an toàn &amp; tiện lợi cho hệ thống thoát nước','','Nắp mương là giải pháp an toàn và tiện lợi cho hệ thống thoát nước, bảo vệ người đi bộ, phương tiện giao thông, hệ thống thoát nước và nâng cao mỹ quan đô thị.','','','','',''),(760,22,'product','man_list','san-pham','Lưới hàng rào | luoi hang rao','','Lưới hàng rào - độ bền, chống ăn mòn mạnh mẽ - sản phẩm đạt tiêu chuẩn ASTM – A123. Sự kết hợp hoàn hảo giữa an toàn và thẩm mỹ.  chất lượng cao cho hệ thống hàng rào của bạn!','','','','',''),(1090,0,'setting','update','setting','CÔNG TY TNHH SẢN XUẤT VÀ XUẤT NHẬP KHẨU NAM LONG','','Nam Long - Chuyên sản xuất và xuất nhập khẩu cơ khí chất lượng. Đối tác đáng tin cậy cho giải pháp vững mạnh và đẳng cấp','','','','',''),(816,74,'product','man','san-pham','Hàng Rào Mạ Kẽm | hàng rào lưới thép mạ kẽm ','',' hàng rào lưới thép mạ kẽm - một giải pháp vững chắc cho không gian an toàn. Với lớp mạ kẽm bảo vệ chống ăn mòn, sản phẩm này không chỉ đảm bảo độ bền bỉ....','','','','',''),(770,75,'product','man','san-pham',' Hàng rào gập tam giác 2 đầu | hang rao gap tam giac 2 dau','','Hàng Rào Mạ kẽm Được sản xuất theo tiêu chuẩn TCVN 9391–2012, từ sợi thép kéo nguội cường độ 500MPa, lực chịu cắt của mối hàn: Min = 250Mpa (2.500kg/cm).','','','','',''),(838,76,'product','man','san-pham','Lưới Hàng Rào | luoi hang rao','','Sản xuất lưới thép hàng rào theo nhu cầu. Cung cấp giá gốc tại xưởng. Đảm bảo chắc chắn, bền lâu và sạch đẹp. Loại mạ kẽm và sơn tĩnh điện.','','','','',''),(815,51,'news','man','tin-tuc','Hàng rào lưới thép | hang rao luoi thep ','','Hàng rào lưới thép - hàng rào lưới thép mạ kẽm | giá rẻ nhất thị trường uy tín chất lượng, bền lâu và sạch đẹp. Có 2 Loại mạ kẽm và loại sơn tĩnh điện... ','','','','',''),(809,36,'news','man','tin-tuc','Hàng rào lưới thép Bền, an toàn và tiết kiệm chi phí','','Hàng rào lưới thép là một trong những loại hàng rào được sử dụng phổ biến nhất hiện nay. Với tính năng bền vững, an toàn và tiết kiệm chi phí, hàng rào lưới','','','{\r\n    &quot;@context&quot;: &quot;https://schema.org&quot;,\r\n    &quot;@type&quot;: &quot;NewsArticle&quot;,\r\n    &quot;mainEntityOfPage&quot;: {\r\n        &quot;@type&quot;: &quot;WebPage&quot;,\r\n        &quot;@id&quot;: &quot;hang-rao-luoi-thep-su-lua-chon-hoan-haohang-rao-luoi-thep-ben-an-toan-va-tiet-kiem-chi-phi&quot;\r\n    },\r\n    &quot;headline&quot;: &quot;Hàng rào lưới thép Bền, an toàn và tiết kiệm chi phí&quot;,\r\n    &quot;image&quot;: &quot;upload/news/moi-17-9443.jpg&quot;,\r\n    &quot;datePublished&quot;: &quot;2024-01-02T21:16:30+07:00&quot;,\r\n    &quot;dateModified&quot;: &quot;2024-03-27T22:15:15+07:00&quot;,\r\n    &quot;author&quot;: {\r\n        &quot;@type&quot;: &quot;Person&quot;,\r\n        &quot;name&quot;: &quot;CÔNG TY TNHH SẢN XUẤT  VÀ XUẤT NHẬP KHẨU NAM LONG&quot;,\r\n        &quot;url&quot;: &quot;&quot;\r\n    },\r\n    &quot;publisher&quot;: {\r\n        &quot;@type&quot;: &quot;Organization&quot;,\r\n        &quot;name&quot;: &quot;CÔNG TY TNHH SẢN XUẤT  VÀ XUẤT NHẬP KHẨU NAM LONG&quot;,\r\n        &quot;logo&quot;: {\r\n            &quot;@type&quot;: &quot;ImageObject&quot;,\r\n            &quot;url&quot;: &quot;upload/photo/logo-6546.png&quot;\r\n        }\r\n    }\r\n}','',''),(777,66,'product','man','san-pham','Hàng rào mạ kẽm | Hang rao ma kem','','Hàng Rào Mạ Kẽm - Nam Long với máy móc công nghệ cao, đảm bảo giá trị vững chắc. độ bền, chống ăn mòn mạnh mẽ. Sự kết hợp hoàn hảo giữa an toàn và thẩm mỹ.  ','','','','',''),(776,69,'product','man','san-pham','Lưới thép sơn tĩnh điện | luoi thep son tinh dien','','hàng rào lưới thép sơn tĩnh điện: hàng rào, tường bảo vệ, bãi đỗ xe, trung tâm thể thao và trang trại. An toàn và linh hoạt, Hy vọng bài viết này đã cung cấp những thông tin hữu ích cho bạn.','','','','',''),(775,70,'product','man','san-pham','Lưới Sắt Hàng Rào | luoi sat hang rao','','lưới sắt hàng rào - Nam Long chất lượng với máy móc công nghệ cao, đảm bảo giá trị vững chắc. Sự kết hợp hoàn hảo giữa độ bền và tính thẩm mỹ.','','','','',''),(810,37,'news','man','tin-tuc','Hàng rào lưới thép hàn tại Tp.HCM | hang rao luoi thep tai Tp.hcm','','Hàng rào lưới thép hàn được sản xuất trên dây chuyền tự động với độ chính xác cao, đảm bảo sự đồng nhất và chất lượng ổn định cho từng bộ sản phẩm.','','','','',''),(774,71,'product','man','san-pham','Hàng rào lưới thép chấn sóng | hang rao luoi thep chan song','','Khám phá lưới rào chất lượng với máy móc công Nghệ cao, đảm bảo giá trị vững chắc  ✓  Sự kết hợp hoàn hảo giữa độ bền và tính thẩm mỹ. Đặt hàng ngay!','','','','',''),(772,72,'product','man','san-pham',' Hàng rào khu công nghiệp | hang rao luoi khu cong nghiep','','hàng rào lưới khu công nghiệp - chất lượng với máy móc công Nghệ cao, đảm bảo giá trị vững chắc  ✓  Sự kết hợp hoàn hảo giữa độ bền và tính thẩm mỹ. Đặt hàng ngay!','','','','',''),(793,52,'news','man','tin-tuc','Hàng rào lưới thép hàn Bảo vệ an toàn và bền vững','','Hàng rào lưới thép hàn: Bảo vệ an toàn và bền vững. Giải pháp đáng tin cậy cho việc phân chia và kiểm soát khu vực. Sản phẩm chất lượng, đảm bảo an ninh và tuổi thọ cao.','','','{\r\n    &quot;@context&quot;: &quot;https://schema.org&quot;,\r\n    &quot;@type&quot;: &quot;NewsArticle&quot;,\r\n    &quot;mainEntityOfPage&quot;: {\r\n        &quot;@type&quot;: &quot;WebPage&quot;,\r\n        &quot;@id&quot;: &quot;hang-rao-luoi-thep-han-bao-ve-an-toan-va-ben-vung&quot;\r\n    },\r\n    &quot;headline&quot;: &quot;Hàng rào lưới thép hàn Bảo vệ an toàn và bền vững&quot;,\r\n    &quot;image&quot;: &quot;upload/news/&quot;,\r\n    &quot;datePublished&quot;: &quot;2024-03-26T09:59:42+07:00&quot;,\r\n    &quot;dateModified&quot;: &quot;2024-03-27T13:46:55+07:00&qu